import sys

# Read the number of shortest paths k
k = int(sys.stdin.readline().strip())

# Determine the number of vertexes n
n = 2
while (2 ** ((n - 2) * (n - 1) // 2)) < k:
    n += 1

# Initialize the adjacency matrix with 'N'
adj_matrix = [['N' for _ in range(n)] for _ in range(n)]

# Set the diagonal to 'N'
for i in range(n):
    adj_matrix[i][i] = 'N'

# Set the edges to form a complete graph
for i in range(1, n):
    for j in range(i + 1, n):
        adj_matrix[i][j] = 'Y'
        adj_matrix[j][i] = 'Y'

# Calculate the number of shortest paths
paths = 1
for i in range(1, n - 1):
    for j in range(i + 1, n):
        if adj_matrix[i][j] == 'Y':
            paths *= 2

# Adjust the number of paths to be exactly k
if paths > k:
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            if paths // 2 >= k:
                paths //= 2
                adj_matrix[i][j] = 'N'
                adj_matrix[j][i] = 'N'

# Output the result
print(n)
for row in adj_matrix:
    print(''.join(row))
